-- =============================================================================
-- Which adjusted goal horizon best fits the PREVIOUS MONTH
-- Single-statement version (Simba JDBC / DataGrip friendly — no TEMP TABLE / DECLARE)
-- =============================================================================
-- Goals export: 2026-08-05 (runs/2026-08-03_rp_ls)
-- Previous month for 2026-08-05 → 2026-07-01 .. 2026-07-31
--
-- Edit the three dates in params CTE if needed.
-- Fit: RMSE(prev-month ROAS_d − adjusted_goal_ratio(d,H))
--   d7_pool  = age>=7, days 1..7   ← primary for "prev month"
--   d30_pool = age>=30, days <=30
-- Blended = WEB + APP + Affiliate
-- =============================================================================

WITH
params AS (
  SELECT
    DATE '2026-08-05' AS goals_run_date,
    DATE '2026-08-05' AS as_of_date,  -- maturity clock
    DATE_TRUNC(DATE_SUB(DATE '2026-08-05', INTERVAL 1 MONTH), MONTH) AS prev_month_start,
    LAST_DAY(DATE_SUB(DATE '2026-08-05', INTERVAL 1 MONTH), MONTH) AS prev_month_end
),

goals_ckpt AS (
  SELECT * FROM UNNEST([
    STRUCT('realprize' AS brand, 'Web' AS population, 7 AS goal_horizon, 1 AS day, 0.2367040588 AS adjusted_goal_ratio),
