base AS (
  SELECT
    CASE brand
      WHEN 'RealPrize' THEN 'realprize'
      WHEN 'LoneStar' THEN 'lonestar'
      ELSE LOWER(brand)
    END AS brand,
    CASE marketing_population
      WHEN 'WEB' THEN 'Web'
      WHEN 'APP' THEN 'App'
      WHEN 'Affiliate' THEN 'Affiliate'
      ELSE marketing_population
    END AS population,
    DATE(cost_date) AS cost_date,
    SUM(cost) AS cost,
    SUM(LTV_D1) AS ltv_1, SUM(LTV_D2) AS ltv_2, SUM(LTV_D3) AS ltv_3,
    SUM(LTV_D4) AS ltv_4, SUM(LTV_D5) AS ltv_5, SUM(LTV_D6) AS ltv_6,
    SUM(LTV_D7) AS ltv_7, SUM(LTV_D14) AS ltv_14, SUM(LTV_D30) AS ltv_30,
    SUM(LTV_D60) AS ltv_60, SUM(LTV_D90) AS ltv_90
  FROM `oceanic-citadel-454608-d2.ETL.Real_Play_Marketing_Cohort`
  CROSS JOIN params p
  WHERE brand IN ('RealPrize', 'LoneStar')
    AND marketing_population IN ('WEB', 'APP', 'Affiliate')
    AND DATE(cost_date) BETWEEN p.prev_month_start AND p.prev_month_end
  GROUP BY 1, 2, 3
),

month_daily AS (
  SELECT * FROM base
  UNION ALL
  SELECT
    brand,
    'Blended' AS population,
    cost_date,
    SUM(cost) AS cost,
    SUM(ltv_1), SUM(ltv_2), SUM(ltv_3), SUM(ltv_4), SUM(ltv_5),
    SUM(ltv_6), SUM(ltv_7), SUM(ltv_14), SUM(ltv_30), SUM(ltv_60), SUM(ltv_90)
  FROM base
  GROUP BY 1, 2, 3
),

unpivoted AS (
  SELECT
    m.brand,
    m.population,
    m.cost_date,
    m.cost,
    u.day,
    u.ltv,
    DATE_DIFF(p.as_of_date, m.cost_date, DAY) AS age_days
  FROM month_daily m
  CROSS JOIN params p
  CROSS JOIN UNNEST([
    STRUCT(1 AS day, m.ltv_1 AS ltv),
    STRUCT(2 AS day, m.ltv_2 AS ltv),
    STRUCT(3 AS day, m.ltv_3 AS ltv),
    STRUCT(4 AS day, m.ltv_4 AS ltv),
    STRUCT(5 AS day, m.ltv_5 AS ltv),
    STRUCT(6 AS day, m.ltv_6 AS ltv),
    STRUCT(7 AS day, m.ltv_7 AS ltv),
    STRUCT(14 AS day, m.ltv_14 AS ltv),
    STRUCT(30 AS day, m.ltv_30 AS ltv),
    STRUCT(60 AS day, m.ltv_60 AS ltv),
    STRUCT(90 AS day, m.ltv_90 AS ltv)
  ]) AS u
),

pooled_roas AS (
  SELECT
    'd7_pool' AS pool,
    brand, population, day,
    SAFE_DIVIDE(SUM(ltv), SUM(cost)) AS month_roas,
    SUM(cost) AS cost,
    COUNT(DISTINCT cost_date) AS n_days,
    MIN(cost_date) AS cohort_min,
    MAX(cost_date) AS cohort_max
  FROM unpivoted
  WHERE age_days >= 7 AND day <= 7
  GROUP BY 1, 2, 3, 4

  UNION ALL

  SELECT
    'd30_pool' AS pool,
    brand, population, day,
    SAFE_DIVIDE(SUM(ltv), SUM(cost)) AS month_roas,
    SUM(cost) AS cost,
    COUNT(DISTINCT cost_date) AS n_days,
    MIN(cost_date) AS cohort_min,
    MAX(cost_date) AS cohort_max
  FROM unpivoted
  WHERE age_days >= 30 AND day <= 30
  GROUP BY 1, 2, 3, 4
),

fit AS (
  SELECT
    pr.pool,
    pr.brand,
    pr.population,
    g.goal_horizon,
    COUNT(*) AS n_points,
    ANY_VALUE(pr.n_days) AS n_cohort_dates,
    ANY_VALUE(pr.cost) AS cost,
    ANY_VALUE(pr.cohort_min) AS cohort_min,
    ANY_VALUE(pr.cohort_max) AS cohort_max,
    SQRT(AVG(POW(pr.month_roas - g.adjusted_goal_ratio, 2))) AS rmse,
    AVG(ABS(pr.month_roas - g.adjusted_goal_ratio)) AS mae,
    AVG(pr.month_roas - g.adjusted_goal_ratio) AS bias_month_minus_goal
  FROM pooled_roas pr
  JOIN goals_ckpt g
    ON g.brand = pr.brand
   AND g.population = pr.population
   AND g.day = pr.day
  WHERE
    pr.pool = 'd7_pool'
    OR (pr.pool = 'd30_pool' AND g.goal_horizon >= 30)
  GROUP BY 1, 2, 3, 4
  HAVING COUNT(*) >= 2
),

best AS (
  SELECT *
  FROM fit
  QUALIFY ROW_NUMBER() OVER (
    PARTITION BY pool, brand, population
    ORDER BY rmse ASC, goal_horizon ASC
  ) = 1
)

SELECT
  p.goals_run_date,
  p.prev_month_start,
  p.prev_month_end,
  p.as_of_date,
  b.pool,
  b.brand,
  b.population,
  b.goal_horizon AS best_horizon,
  ROUND(b.rmse, 6) AS rmse,
  ROUND(b.mae, 6) AS mae,
  ROUND(b.bias_month_minus_goal, 6) AS bias,
  b.n_points,
  b.n_cohort_dates,
  ROUND(b.cost, 2) AS cost,
  b.cohort_min,
  b.cohort_max
FROM best b
CROSS JOIN params p
ORDER BY
  CASE b.pool WHEN 'd7_pool' THEN 1 ELSE 2 END,
  b.brand,
  b.population;
